use super::*;
use crate::{DslValue,retained_clone::RetainedCloneSource,retirement::controlled::ControlledRetirement};
use crate::retained_clone::{RetainedClone,RetainedCloneCursor};
const BODY:usize=32768;
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=BODY,"original map header exceeds native policy: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn heap<T>(f:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(f)}
fn source(v:DslValue)->RetainedCloneSource<DslValue>{let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(v,(),RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),..grant(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})}).unwrap_or_else(|_|panic!("actual map source admission")).0}
fn drain<T:RetireOwned>(v:T){let mut r=ControlledRetirement::new(v).unwrap_or_else(|_|panic!("actual map source supports retirement"));for _ in 0..100000{if r.terminal_is_empty(){return}let g=grant(r.next_demand(BODY).unwrap());let(p,h)=heap(||r.step(g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));}panic!("native map physical closure stalled")}
fn denials(g:RetainedCloneGrant)->Vec<RetainedCloneGrant>{let mut out=vec![RetainedCloneGrant{maximum_items:0,..g}];if g.maximum_copy_bytes>0{out.push(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-1,..g})}if g.maximum_capacity_bytes>0{out.push(RetainedCloneGrant{maximum_capacity_bytes:g.maximum_capacity_bytes-1,..g})}if g.maximum_release_bytes>0{out.push(RetainedCloneGrant{maximum_release_bytes:g.maximum_release_bytes-1,..g})}if g.maximum_depth>0{out.push(RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g})}out}
struct Turn{grant:RetainedCloneGrant,issued:bool}
impl crate::NativeDecodeConstructionRecipient for Turn{fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.issued);assert!(retained_clone_grant_admits(self.grant,d));self.issued=true;Ok(self.grant)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(self.issued);assert_eq!(g,self.grant);assert!(p.fits(g));Ok(())}}
fn advance(r:&mut NativeMapReceiver<DslValue,String>,s:&RetainedCloneSource<DslValue>,c:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{c.with_construction_recipient(&mut Turn{grant:g,issued:false},|c|r.advance(s.borrow(),c,BODY,g))}
#[test]fn original_map_receiving_matches_fixture_and_closes_every_partial_owner(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){for cut in law["cancelCuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain(std::iter::once(100000)){
  let make=||DslValue::Object(case["entries"].as_array().unwrap().iter().map(|e|(e[0].as_str().unwrap().into(),DslValue::String(e[1].as_str().unwrap().into()))).collect());let s=source(make());let foreign=source(make());
  let g=grant(<OrderedMap<String> as NativeReceive<DslValue>>::receive_birth_demand());let((mut r,p),h)=heap(||<OrderedMap<String> as NativeReceive<DslValue>>::begin_receive(g).unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let mut callback=|_|true;let mut c=NativeDecodeControl::new(1<<26,&mut callback);
  for _ in 0..cut{if r.output_ready(){break}let d=r.demands(s.borrow(),BODY).unwrap();let g=grant(d);for denied in denials(g){let(p,h)=heap(||advance(&mut r,&s,&mut c,denied).unwrap());assert_eq!(p.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.demands(s.borrow(),BODY).unwrap(),d)}let(p,h)=heap(||advance(&mut r,&s,&mut c,g).unwrap());assert!(p.progress().fits(g),"actual map receipt {p:?} exceeds {g:?}");assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));assert!(r.demands(foreign.borrow(),BODY).is_err())}
  if r.output_ready(){let g=grant(r.take_demand().unwrap());let((map,p),h)=heap(||r.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let entries:Vec<_>=map.iter().map(|(k,v)|serde_json::json!([k,v])).collect();assert_eq!(serde_json::Value::Array(entries),case["expected"]);drain(map)}else{assert_ne!(cut,100000,"actual map preparation stalled")}
  r.begin_close();for _ in 0..100000{if r.terminal_is_empty(){break}let d=r.close_demands(BODY).unwrap();let g=grant(d);for denied in denials(g){let(p,h)=heap(||r.close_step(denied).unwrap());assert_eq!(p.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.close_demands(BODY).unwrap(),d)}let(p,h)=heap(||r.close_step(g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));}assert!(r.terminal_is_empty());drain(s);drain(foreign);
 }}
}

#[test]fn ordered_map_original_alias_clone_keeps_its_root_and_closes_all_denied_prefixes(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../🗂️ordered/🧬️alias.json")).unwrap();
 for cut in law["cancelCuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain(std::iter::once(100)){
  let map:OrderedMap<String>=law["entries"].as_array().unwrap().iter().map(|v|(v[0].as_str().unwrap().to_string(),v[1].as_str().unwrap().to_string())).collect();let identity=map.original_root_identity();let d=RetainedCloneSource::<OrderedMap<String>>::owned_constructor_demand::<()>();let s=RetainedCloneSource::admit_owned(map,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<OrderedMap<String>>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).unwrap_or_else(|_|panic!("actual immutable map source")).0;
  let mut cursor=OrderedMap::<String>::retained_clone_cursor();for _ in 0..cut{if cursor.output_ready(){break}let d=cursor.advance_demands(s.borrow(),4096).unwrap();assert!(d.copy_bytes<=4096);let g=grant(d);for denied in denials(g){let(step,h)=heap(||cursor.advance(s.borrow(),4096,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(cursor.advance_demands(s.borrow(),4096).unwrap(),d)}let(step,h)=heap(||cursor.advance(s.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(h.0,law["aliasCapacityBytes"].as_u64().unwrap()as usize)}
  if cut==100{assert!(cursor.output_ready());let(value,h)=heap(||cursor.take().unwrap());assert_eq!(h,(0,0));assert_eq!(value.original_root_identity(),identity);assert!(law["sharedRoot"].as_bool().unwrap());drain(value)}cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty(){break}let d=cursor.close_demands(4096).unwrap();let g=grant(d);for denied in denials(g){let(step,h)=heap(||cursor.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(cursor.close_demands(4096).unwrap(),d)}let(step,h)=heap(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(cursor.terminal_is_empty());drain(s)
 }
}
